// ─── Helper ───────────────────────────────────────────────────────────────────
function brandCard(name, svgConst) {
  const label = name.replace(/-original$/, '').replace(/-dark$/, ' (dark)').replace(/-/g, ' ');
  const isDark = name.endsWith('-dark');
  return `<div style="display:flex;flex-direction:column;align-items:center;gap:8px;padding:16px 12px;border-radius:8px;border:1px solid var(--color-border-default);background:${isDark ? '#1f2a37' : 'var(--color-bg-white)'};">
    <div style="width:48px;height:48px;display:flex;align-items:center;justify-content:center;">${svgConst}</div>
    <span style="font-size:10px;color:${isDark ? 'var(--color-border-light)' : 'var(--color-text-secondary)'};text-align:center;line-height:1.3;">${label}</span>
  </div>`;
}

const SOCIAL_ICONS = [["facebook-original", FACEBOOK_ORIGINAL], ["facebook-dark", FACEBOOK_DARK], ["linkedin-original", LINKEDIN_ORIGINAL], ["linkedin-dark", LINKEDIN_DARK], ["youtube-original", YOUTUBE_ORIGINAL], ["youtube-dark", YOUTUBE_DARK], ["tiktok-original", TIKTOK_ORIGINAL], ["tiktok-dark", TIKTOK_DARK], ["pinterest-original", PINTEREST_ORIGINAL], ["pinterest-dark", PINTEREST_DARK], ["snapchat-original", SNAPCHAT_ORIGINAL], ["snapchat-dark", SNAPCHAT_DARK]];
const ECOMMERCE_ICONS = [["amazon-original", AMAZON_ORIGINAL], ["amazon-dark", AMAZON_DARK], ["shopify-original", SHOPIFY_ORIGINAL], ["shopify-dark", SHOPIFY_DARK], ["ebay-original", EBAY_ORIGINAL], ["ebay-dark", EBAY_DARK]];
const ADVERTISING_ICONS = [["google-original", GOOGLE_ORIGINAL], ["google-dark", GOOGLE_DARK], ["google-ads-original", GOOGLE_ADS_ORIGINAL], ["google-ads-dark", GOOGLE_ADS_DARK]];
const FINANCE_PAYMENTS_ICONS = [["stripe-original", STRIPE_ORIGINAL], ["stripe-dark", STRIPE_DARK], ["paypal-original", PAYPAL_ORIGINAL], ["paypal-dark", PAYPAL_DARK], ["plaid-original", PLAID_ORIGINAL], ["plaid-dark", PLAID_DARK], ["quickbooks-original", QUICKBOOKS_ORIGINAL], ["quickbooks-dark", QUICKBOOKS_DARK], ["xero-original", XERO_ORIGINAL], ["xero-dark", XERO_DARK]];
const ENTERPRISE_ICONS = [["sps-commerce-original", SPS_COMMERCE_ORIGINAL], ["sps-commerce-dark", SPS_COMMERCE_DARK], ["netsuite-original", NETSUITE_ORIGINAL], ["netsuite-dark", NETSUITE_DARK]];

// ─── Stories ──────────────────────────────────────────────────────────────────

export const AllBrandIcons = {
    name: 'All brand icons',
  parameters: {
    controls: { disable: true },
    docs: {
      description: {
        story: 'All 36 brand icons: 18 original-color variants and 18 dark variants. Dark variants are shown on dark backgrounds.',
      },
      source: {
        code: `<!-- Use the SVG directly from Figma or copy from this story source -->
<!-- Example: Facebook original -->
<img src="path/to/facebook-original.svg" alt="Facebook" width="24" height="24" />`,
      },
    },
  },
  render: () => {
    const groups = {

      'Social': SOCIAL_ICONS,
      'E-commerce': ECOMMERCE_ICONS,
      'Advertising': ADVERTISING_ICONS,
      'Finance & Payments': FINANCE_PAYMENTS_ICONS,
      'Enterprise': ENTERPRISE_ICONS,
    };

    const sections = Object.entries(groups).map(([title, icons]) => {
      const cards = icons.map(([name, svg]) => brandCard(name, svg)).join('');
      return `<div style="margin-bottom:32px;">
        <h3 style="font-size:var(--text-xs);font-weight:var(--font-semibold);color:var(--color-text-secondary);text-transform:uppercase;letter-spacing:0.06em;margin:0 0 10px;padding-bottom:6px;border-bottom:1px solid var(--color-border-default);">${title} <span style="font-weight:var(--font-normal);opacity:.6;">(${icons.length})</span></h3>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(100px,1fr));gap:8px;">${cards}</div>
      </div>`;
    });

    return `<div style="font-family:inherit;padding:4px 0;">${sections.join('')}</div>`;
  },
};
